-- QA exclusivement. Appliquer la migration 20261120090000_historical_calendar_profile avant ce script.
-- Ne pas exécuter sur production ; préparation distincte requise.
BEGIN;
LOCK TABLE "Period","ClassPeriod","SchoolClass","SchoolYear","Evaluation","ResultSnapshot","ReportCard","Grade","Enrollment" IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
IF current_setting('neon.branch_id',true) IS DISTINCT FROM 'br-patient-boat-b90nknp0' OR (SELECT count(*) FROM "_prisma_migrations" WHERE finished_at IS NOT NULL AND rolled_back_at IS NULL)<>7 OR (SELECT count(*) FROM "Period" WHERE profile='SECONDAIRE_TECHNIQUE')<>1 OR (SELECT count(*) FROM "ClassPeriod" cp JOIN "Period" p ON p.id=cp."periodId" WHERE p.profile='SECONDAIRE_TECHNIQUE' AND p.code='P1')<>19 OR (SELECT count(*) FROM "ClassPeriod" cp JOIN "Period" p ON p.id=cp."periodId" WHERE p.profile='SECONDAIRE_TECHNIQUE' AND p.code='P1' AND cp."closedAt" IS NULL AND cp."publishedAt" IS NULL AND NOT EXISTS(SELECT 1 FROM "Evaluation" e WHERE e."classPeriodId"=cp.id) AND NOT EXISTS(SELECT 1 FROM "ResultSnapshot" r WHERE r."classPeriodId"=cp.id))<>18 OR NOT ((SELECT md5(coalesce(string_agg(to_jsonb(r)::text,'' ORDER BY r.id),'')) FROM "ResultSnapshot" r)='2a4608438a444c16fed0d16a3d75197b' AND (SELECT md5(coalesce(string_agg(to_jsonb(r)::text,'' ORDER BY r.id),'')) FROM "ReportCard" r)='58b412836d4657a341a305a2c8f50312' AND (SELECT md5(coalesce(string_agg(to_jsonb(g)::text,'' ORDER BY g.id),'')) FROM "Grade" g)='5ce1476b6570ab23f9ad19ffca161f08') THEN RAISE EXCEPTION 'QA baseline mismatch'; END IF;
END $$;
DELETE FROM "ClassPeriod" cp USING "Period" p WHERE cp."periodId"=p.id AND p.profile='SECONDAIRE_TECHNIQUE' AND p.code='P1' AND cp."closedAt" IS NULL AND cp."publishedAt" IS NULL AND NOT EXISTS(SELECT 1 FROM "Evaluation" e WHERE e."classPeriodId"=cp.id) AND NOT EXISTS(SELECT 1 FROM "ResultSnapshot" r WHERE r."classPeriodId"=cp.id);
WITH archived AS (UPDATE "Period" SET profile='HISTORIQUE',source=source||' ; ancien profil SECONDAIRE_TECHNIQUE ; P1 conservée pour résultats clôturés de 6A' WHERE profile='SECONDAIRE_TECHNIQUE' AND code='P1' RETURNING id) INSERT INTO "AuditEntry" (action,"targetType","targetId",details) SELECT 'SCHOOL_UPDATED','Period',id,jsonb_build_object('fromProfile','SECONDAIRE_TECHNIQUE','toProfile','HISTORIQUE','purpose','préservation des résultats clôturés de 6A ; dates originales inchangées') FROM archived;
INSERT INTO "Period" ("schoolYearId",profile,code,label,kind,"parentCode","startsOn","endsOn",position,source) SELECT y.id,'SECONDAIRE_TECHNIQUE',v.code,v.label,v.kind,v.parent,v.start_date::date,v.end_date::date,v.pos::integer,'REFERENCE_A_VERIFIER : calendrier national 2026-2027' FROM "SchoolYear" y CROSS JOIN (VALUES ('P1','1re période — secondaire','PERIODE','S1','2026-09-01','2026-11-04','1'),('P2','P2 — SECONDAIRE_TECHNIQUE','PERIODE','S1','2026-11-09','2027-02-17','2'),('P3','P3 — SECONDAIRE_TECHNIQUE','PERIODE','S2','2027-02-22','2027-04-24','3'),('P4','P4 — SECONDAIRE_TECHNIQUE','PERIODE','S2','2027-04-26','2027-07-02','4'),('S1','S1 — SECONDAIRE_TECHNIQUE','SEMESTRE','ANNEE','2026-09-01','2027-02-17','5'),('S2','S2 — SECONDAIRE_TECHNIQUE','SEMESTRE','ANNEE','2027-02-22','2027-07-02','6'),('E1','E1 — SECONDAIRE_TECHNIQUE','EXAMEN','S1','2027-02-09','2027-02-17','7'),('E2','E2 — SECONDAIRE_TECHNIQUE','EXAMEN','S2','2027-05-24','2027-06-01','8'),('REPECHAGE','REPECHAGE — SECONDAIRE_TECHNIQUE','REPECHAGE','ANNEE','2027-06-15','2027-06-16','9'),('ANNEE','Année scolaire — secondaire','ANNUEL',NULL,'2026-09-01','2027-07-02','1000')) v(code,label,kind,parent,start_date,end_date,pos) WHERE y.code='2026-2027';
INSERT INTO "ClassPeriod" ("classId","periodId","schoolYearId") SELECT c.id,p.id,c."schoolYearId" FROM "SchoolClass" c JOIN "SchoolYear" y ON y.id=c."schoolYearId" JOIN "Period" p ON p."schoolYearId"=c."schoolYearId" AND p.profile=c.cycle WHERE y.code='2026-2027' AND c.cycle='SECONDAIRE_TECHNIQUE' AND p.kind NOT IN ('EVENEMENT','EVEIL') ON CONFLICT DO NOTHING;
UPDATE "SchoolSettings" SET profiles=jsonb_set(profiles,'{RDC_CATALOGUE_RECETTE_V1,limitations}','["Le moteur maternel actuel ne calcule pas les composants EVEIL : ne pas créer de contextes d''évaluation sur ces dates.","P1 historique conservée dans le profil réservé HISTORIQUE, exclue du calendrier pédagogique actif.","6A et ancienne 5A conservées sans changement de programme ; ne pas effacer les résultats figés.","Toutes les pondérations extrapolées sont provisoires ; aucune publication officielle."]'::jsonb) WHERE id='school';
DO $$ BEGIN IF (SELECT count(*) FROM "Period" WHERE profile='SECONDAIRE_TECHNIQUE')<>10 OR (SELECT count(*) FROM "ClassPeriod" cp JOIN "Period" p ON p.id=cp."periodId" WHERE p.profile='SECONDAIRE_TECHNIQUE')<>180 OR (SELECT count(*) FROM "ClassPeriod" cp JOIN "Period" p ON p.id=cp."periodId" JOIN "SchoolClass" c ON c.id=cp."classId" WHERE p.profile='HISTORIQUE' AND c.code='6A' AND cp."closedAt" IS NOT NULL AND cp."publishedAt" IS NULL)<>1 OR NOT ((SELECT md5(coalesce(string_agg(to_jsonb(r)::text,'' ORDER BY r.id),'')) FROM "ResultSnapshot" r)='2a4608438a444c16fed0d16a3d75197b' AND (SELECT md5(coalesce(string_agg(to_jsonb(r)::text,'' ORDER BY r.id),'')) FROM "ReportCard" r)='58b412836d4657a341a305a2c8f50312' AND (SELECT md5(coalesce(string_agg(to_jsonb(g)::text,'' ORDER BY g.id),'')) FROM "Grade" g)='5ce1476b6570ab23f9ad19ffca161f08') OR (SELECT count(*) FROM "Student")<>93 OR (SELECT count(*) FROM "Enrollment")<>94 OR (SELECT count(*) FROM "ClassSubject")<>476 THEN RAISE EXCEPTION 'QA postconditions failed'; END IF; END $$;
SELECT p.profile,p.code,p.kind,p."parentCode",p."startsOn",p."endsOn",count(cp.id) AS contexts FROM "Period" p LEFT JOIN "ClassPeriod" cp ON cp."periodId"=p.id WHERE p.profile IN ('SECONDAIRE_TECHNIQUE','HISTORIQUE') GROUP BY p.id ORDER BY p.profile,p.position;
COMMIT;
